mat2 rot(float a) {
    float s = sin(a);
    float c = cos(a);
    return mat2(c, s, -s, c);
}


float fGDF(vec3 p, float r, int begin, int end) {
	float d = 0.;
	for (int i = begin; i <= end; ++i)
		d = max(d, abs(dot(p, GDFVectors[i])));
	return d - r;
}

// from iq
float octahedron( vec3 p, float s) {
  p = abs(p);
  return (p.x+p.y+p.z-s)*0.57735027;
}

float dodecahedron(vec3 p, float r) {
	return fGDF(p, r, 13, 18);
}


float icosahedron(vec3 p, float r) {
	return fGDF(p, r, 3, 12);
}

float box(vec3 p, vec3 r) {
	vec3 d = abs(p) - r;
    return length(max(d, 0.0)) + 
        min(max(d.x, max(d.y, d.z)), 0.0);
}

float cube(vec3 p, float r) {
    return box(p, vec3(r));
}


float tetrahedron(vec3 p, float r) {

    // basically cutting a cube at the diagonal and scaling/centering it.
    p.yz *= rot(PI/2.);

    p.z -= ISQR2*r;
    vec3 bp = p;
    p.z *=  0.5;
    p.z -= ISQR2*r;



    return max(cube(p, r), bp.z);
}


float smoothrect(float x) {
    return smoothstep(0., .25, mod(x, 1.5))*smoothstep(.25, 0., mod(x, 1.5)-.75);
}



vec3 kalei(vec3 p) {
    for(int i=0; i<4; i++) {
        p = abs(p) - .1;
        p.xy *= rot(TAU*1./3.);
        p.yz *= rot(TAU*1./16.+(tt-7.5)*.2);
    }
    return p;
}

vec3 fold(vec3 p) {

    float c = cos(PI/5.), s = sqrt(.75 - c*c);

    vec3 n = vec3(-.5, -c, s);

    p = abs(p);;
    p -= 2.*min(0., dot(p, n))*n;

    p.xy = abs(p.xy);
    p -= 2.*min(0., dot(p, n))*n;

    p.xy = abs(p.xy);
    p -= 2.*min(0., dot(p, n))*n;

    return p;
}

float map(vec3 p) {

    vec3 bp = p;





    p = bp;
    p = fold(p);

    float iv = 0., d1 = 0., d2 = 0., it = 0., ts = 0.;


    float il = 0.5;

    ts = mod(tt, il*5.);
    iv = floor(ts/il);
    it = mod(ts, il);

    float s = 1.5;

    if(iv < 1.) {
        d1 = tetrahedron(p, 1.*s);
        d2 = cube(p, 0.8*s);
    } else if(iv < 2.) {
        d1 = cube(p, 0.8*s);
        d2 = octahedron(p, 1.5*s);
    } else if(iv < 3.) {
        d1 = octahedron(p, 1.5*s);
        d2 = dodecahedron(p, 1.*s);
     } else if(iv < 4.) {
        d1 = dodecahedron(p, 1.*s);
        d2 = icosahedron(p, 1.0*s);;
    } else {
        d1 = icosahedron(p, 1.0*s);;
       // p = kalei(p);
        d2 = tetrahedron(p, 1.*s);
    }

    float d = mix(d1, d2, smoothstep(.5, 1., it));
    return d;

}

vec3 getNormal(vec3 p) {

    float eps = 0.007;
    vec2 e = vec2(eps, -eps);
    return normalize( e.xyy*map(p+e.xyy) + e.yyx*map(p+e.yyx) +
                            e.yxy*map(p+e.yxy) + e.xxx*map(p+e.xxx));

}

vec3 getRayDir(vec2 uv, vec3 p, vec3 l, float z) {


    // camera system
    vec3 f = normalize(l - p),  // forward vector
         r = normalize(cross(vec3(0, 1, 0), f)), // right vector
         u = cross(f, r), // up vector
         c = p + f * z, // center of virtual screen
         i = c + uv.x * r + uv.y * u, // intersection with screen
         rd = normalize(i - p);  // ray direction

    return rd;

}


float rayMarch(vec3 ro, vec3 rd, out vec3 p, float sig) {
    float i, t, d = 0.1;

    p = ro;

    for(i=0.; i<100.; i++) {

        d = sig*map(p);

        if(abs(d) < 0.001 || t > 50.) break;

        p += rd*d;
        t += d;
    }

    return d;

}

vec3 refractCol(vec3 p, vec3 rd, vec3 n, float ior) {

        vec3 rdIn = refract(rd, n, 1./ior);

        vec3 pEnter = p - n * 0.003;

        vec3 pExit;
        float dIn = rayMarch(pEnter, rdIn, pExit, -1.0);

        vec3 nExit = -getNormal(pExit);
        vec3 rdOut = refract(rdIn, nExit, ior);

        if(dot(rdOut, rdOut) == 0.0) rdOut = reflect(rdIn, nExit);

        return  rdOut.rgb;

}

